      SUBROUTINE TWIT2ECC     DETERMINES CONTRIBUTION OF SECOND-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF ETA FUNCTIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETATC.CIN'      INCLUDE 'T.CIN'CC     TRANSFORM DERIVATIVE OF ETA FUNCTIONC     SECOND ORDER TERMSC      DO 20 J = 1, 5      IND = 0      SS = ETAT(J)      DO 10 L2 = 1, 6      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + T(J,IND)*(ETA(L1)*ETAV(L2,NV2)     1                  + ETAV(L1,NV2)*ETA(L2))   10 CONTINUE      ETAT(J) = SS   20 CONTINUEC      RETURN      END